<?php
declare(strict_types=1);

require __DIR__ . '/app/bootstrap.php';
$categoryId = (int) ($_GET['category'] ?? 0); $districtId = (int) ($_GET['district'] ?? 0); $page = max(1,(int)($_GET['page']??1)); $perPage=12;
$where = ["u.role = 'provider'", "u.status = 'active'", "pp.verification_status = 'verified'"]; $params=[];
if ($categoryId>0) { $where[]='EXISTS (SELECT 1 FROM provider_categories pcx WHERE pcx.provider_id=u.id AND pcx.category_id=?)'; $params[]=$categoryId; }
if ($districtId>0) { $where[]='EXISTS (SELECT 1 FROM provider_districts pdx WHERE pdx.provider_id=u.id AND pdx.district_id=?)'; $params[]=$districtId; }
$whereSql=implode(' AND ',$where);
$count=db()->prepare("SELECT COUNT(*) FROM users u JOIN provider_profiles pp ON pp.user_id=u.id WHERE $whereSql"); $count->execute($params); $total=(int)$count->fetchColumn(); $pages=max(1,(int)ceil($total/$perPage)); $page=min($page,$pages);
$sql="SELECT u.id,u.full_name,pp.headline,pp.bio,pp.years_experience,GROUP_CONCAT(DISTINCT c.name ORDER BY c.sort_order SEPARATOR '||') category_names,COALESCE(rv.rating_avg,0) rating_avg,COALESCE(rv.review_count,0) review_count FROM users u JOIN provider_profiles pp ON pp.user_id=u.id JOIN provider_categories pc ON pc.provider_id=u.id JOIN categories c ON c.id=pc.category_id LEFT JOIN (SELECT provider_id,AVG(rating) rating_avg,COUNT(*) review_count FROM reviews WHERE status='published' GROUP BY provider_id) rv ON rv.provider_id=u.id WHERE $whereSql GROUP BY u.id,u.full_name,pp.headline,pp.bio,pp.years_experience,rv.rating_avg,rv.review_count ORDER BY rv.review_count DESC,u.created_at DESC LIMIT $perPage OFFSET ".(($page-1)*$perPage);
$statement=db()->prepare($sql); $statement->execute($params); $providers=$statement->fetchAll();
$categoryRows=categories(); $districtRows=districts();
$pageTitle='Proveedores'; $pageDescription='Explora perfiles de proveedores aprobados en Lima Metropolitana y Callao.'; $activeNav='providers';
require __DIR__.'/templates/header.php';
?>
<section class="section section-soft"><div class="container"><div class="section-head"><div><p class="kicker">Directorio público</p><h1>Encuentra un proveedor</h1></div><p>Filtra por categoría y distrito. El contacto se habilita al aceptar una propuesta dentro de la plataforma.</p></div>
<form class="filter-bar" method="get"><div class="field"><label for="category">Categoría</label><select id="category" name="category"><option value="0">Todas</option><?php foreach($categoryRows as $category):?><option value="<?= (int)$category['id']?>"<?=selected($categoryId,$category['id'])?>><?=e($category['name'])?></option><?php endforeach;?></select></div><div class="field"><label for="district">Distrito</label><select id="district" name="district"><option value="0">Todos</option><?php foreach($districtRows as $district):?><option value="<?= (int)$district['id']?>"<?=selected($districtId,$district['id'])?>><?=e($district['name'])?></option><?php endforeach;?></select></div><button class="btn btn-primary" type="submit">Buscar</button></form>
<?php if($providers===[]):?><div class="panel empty-state"><span class="empty-icon"><?=icon('search')?></span><h3>No encontramos proveedores con esos filtros</h3><p>Prueba otra categoría o distrito. La oferta se ampliará progresivamente.</p></div><?php else:?><div class="provider-grid"><?php foreach($providers as $provider):$names=explode('||',(string)$provider['category_names']);?><article class="provider-card"><div class="provider-card-top"><span class="avatar"><?=e(user_initials($provider['full_name']))?></span><div class="provider-card-name"><strong><?=e($provider['full_name'])?></strong><span><?=e($provider['headline']?:'Proveedor de servicios')?></span></div></div><div class="provider-card-body"><div class="chip-row"><?php foreach(array_slice($names,0,3) as $name):?><span class="chip"><?=e($name)?></span><?php endforeach;?></div><p><?=e(mb_strimwidth((string)($provider['bio']?:'Perfil aprobado por el equipo.'),0,150,'…'))?></p><div class="card-footer"><span class="rating"><?=icon('star')?><?= (int)$provider['review_count']>0?e(number_format((float)$provider['rating_avg'],1)).' · '.(int)$provider['review_count']:'Sin reseñas aún'?></span><a class="btn btn-secondary btn-small" href="<?=e(url('provider.php?id='.(int)$provider['id']))?>">Ver perfil</a></div></div></article><?php endforeach;?></div><?php endif;?>
<?php if($pages>1):?><nav class="pagination" aria-label="Paginación"><?php for($i=1;$i<=$pages;$i++):?><a class="<?=$i===$page?'active':''?>" href="?category=<?=$categoryId?>&amp;district=<?=$districtId?>&amp;page=<?=$i?>"><?=$i?></a><?php endfor;?></nav><?php endif;?></div></section>
<?php require __DIR__.'/templates/footer.php';?>
